    /// <summary>
    /// Path normalization utilities for cross-source path matching.
    /// Mirrors the consumer-side helper of the same name to keep identity matching consistent.
    /// </summary>
    static class PathHelper
    {
        /// <summary>Normalize path separators to backslash (Windows native).</summary>
        public static string NormalizeSeparators(string path)
        {
            return path.Replace('/', '\\');
        }

        /// <summary>
        /// Quote a single argument for Windows CreateProcess argument string.
        /// Handles embedded double-quotes and trailing backslashes per the
        /// CommandLineToArgvW parsing rules.
        /// </summary>
        public static string QuoteArg(string arg)
        {
            // Fast path: no special characters — just wrap in quotes
            if (arg.IndexOf('"') < 0 && arg.IndexOf('\\') < 0)
                return $"\"{arg}\"";

            var sb = new StringBuilder(arg.Length + 4);
            sb.Append('"');
            for (int i = 0; i < arg.Length; i++)
            {
                // Count consecutive backslashes
                int backslashes = 0;
                while (i < arg.Length && arg[i] == '\\')
                {
                    backslashes++;
                    i++;
                }

                if (i == arg.Length)
                {
                    // Trailing backslashes: double them (they precede the closing quote)
                    sb.Append('\\', backslashes * 2);
                }
                else if (arg[i] == '"')
                {
                    // Backslashes before a quote: double them + escape the quote
                    sb.Append('\\', backslashes * 2 + 1);
                    sb.Append('"');
                }
                else
                {
                    // Backslashes not before a quote: leave them as-is
                    sb.Append('\\', backslashes);
                    sb.Append(arg[i]);
                }
            }
            sb.Append('"');
            return sb.ToString();
        }
    }

    /// <summary>
    /// Case-insensitive, separator-normalizing path comparer.
    /// Drop-in replacement for StringComparer.OrdinalIgnoreCase on
    /// dictionaries and hashsets that store file paths.
    /// </summary>
    class PathComparer : IEqualityComparer<string>
    {
        public static readonly PathComparer Instance = new PathComparer();

        public bool Equals(string x, string y)
        {
            if (ReferenceEquals(x, y)) return true;
            if (x is null || y is null) return false;
            if (x.Length != y.Length) return false;
            for (int i = 0; i < x.Length; i++)
            {
                var cx = x[i] == '/' ? '\\' : x[i];
                var cy = y[i] == '/' ? '\\' : y[i];
                if (char.ToUpperInvariant(cx) != char.ToUpperInvariant(cy))
                    return false;
            }
            return true;
        }

        public int GetHashCode(string obj)
        {
            if (obj is null) return 0;
            unchecked
            {
                int hash = (int)2166136261;
                for (int i = 0; i < obj.Length; i++)
                {
                    var c = obj[i] == '/' ? '\\' : obj[i];
                    c = char.ToUpperInvariant(c);
                    hash = (hash ^ c) * 16777619;
                }
                return hash;
            }
        }
    }

    /// <summary>
    /// Tee writer — sends all Console.WriteLine output to both console and a log file.
    /// Thread-safe via lock on the file writer. AutoFlush keeps tail -f live — the
    /// flushed bytes land in the OS cache, which is what a reader sees, so live
    /// tailing never needed the durability of WriteThrough. The log is deliberately
    /// NOT WriteThrough: forcing a durable device write on every line turned a
    /// 72k-entry --audit save into ~11 min (71.5k synchronous flushes). Thread-safety
    /// lives in the lock + FileOnly's one-block-per-lock, not in the flush mode.
    /// </summary>
    class TeeWriter : TextWriter
    {
        readonly TextWriter _console;
        readonly StreamWriter _file;
        readonly object _lock = new object();
        bool _disposed;

        public TeeWriter(TextWriter console, string logPath)
        {
            _console = console;
            _file = new StreamWriter(
                new FileStream(logPath, FileMode.Create, FileAccess.Write, FileShare.Read, 4096, FileOptions.SequentialScan),
                new UTF8Encoding(false))
            { AutoFlush = true };
        }

        public override Encoding Encoding => _console.Encoding;
        public override void Write(char value) { _console.Write(value); lock (_lock) { _file.Write(value); } }
        public override void Write(string? value) { _console.Write(value); lock (_lock) { _file.Write(value); } }
        public override void WriteLine(string? value) { _console.WriteLine(value); lock (_lock) { _file.WriteLine(value); } }
        public override void WriteLine() { _console.WriteLine(); lock (_lock) { _file.WriteLine(); } }

        /// <summary>Write a (possibly multi-line) block to the LOG FILE ONLY — the console
        /// never sees it. One call = one lock hold, so concurrent workers' blocks land in
        /// the log whole, never interleaved. Used for the high-volume --audit verdict
        /// traces that would flood the console at per-entry-per-save volume.</summary>
        public void FileOnly(string block)
        {
            lock (_lock)
            {
                if (_disposed) return;
                _file.WriteLine(block);
            }
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing) { lock (_lock) { if (!_disposed) { _disposed = true; _file.Flush(); _file.Dispose(); } } }
            base.Dispose(disposing);
        }
    }

    class Program
    {
        static int _analyzeCount;
        static long _analyzeTicksTotal;
        // Phantom-key detector: every extractor path NavDbl/OptN looks up is recorded as queried,
        // and (when it resolves to a number) as resolved. A path queried but NEVER resolved across a
        // scan is a wrong/absent key read as a default — how spectralFlatness stayed 0 for six months.
        // Distinct sets (bounded to the ~80 keys read), thread-safe for the parallel workers.
        static readonly System.Collections.Concurrent.ConcurrentDictionary<string, byte> _navQueried
            = new System.Collections.Concurrent.ConcurrentDictionary<string, byte>(StringComparer.Ordinal);
        static readonly System.Collections.Concurrent.ConcurrentDictionary<string, byte> _navResolved
            = new System.Collections.Concurrent.ConcurrentDictionary<string, byte>(StringComparer.Ordinal);
        static bool _phantomReported;
        // Live count of running Essentia subprocesses — the saturation gauge on the
        // progress line ("ess N/P"). Debugging aid: if this sits well below the
        // parallelism while new work remains, workers are parked on something other
        // than analysis (disk, staging, a lane tail) and THAT is worth hunting.
        static int _essentiaActive;
        // Trailing peak of _essentiaActive, displayed instead of the instantaneous
        // count and reset by each progress line. The line is printed by a worker at
        // its own track boundary — an instant when its OWN slot is by definition
        // released — so a raw sample structurally tops out at P-1 on a saturated
        // box and reads as "missing one worker". The peak-since-last-line has no
        // such observer bias: if all P ran together at any point in the window,
        // the gauge says P.
        static int _essentiaPeak;
        // In-flight worker count: incremented past the pause gate, decremented in the
        // per-track finally. The Ctrl+C handler drains this to 0 before it prints the
        // summary and prompts, so the summary reflects a settled (idle) state.
        static int _inFlight;

        /// <summary>CAS-max: record a newly observed concurrent-essentia count into
        /// the trailing peak. Monotonic within a window — a lower observation never
        /// lowers the peak.</summary>
        internal static void RaiseEssentiaPeak(int observed)
        {
            int oldPeak;
            while (observed > (oldPeak = Volatile.Read(ref _essentiaPeak)))
                if (Interlocked.CompareExchange(ref _essentiaPeak, observed, oldPeak) == oldPeak)
                    break;
        }

        /// <summary>Read-and-reset the trailing peak (the display consumes the
        /// window; the next window starts at 0).</summary>
        internal static int TakeEssentiaPeak() => Interlocked.Exchange(ref _essentiaPeak, 0);

        // ---- Scan telemetry (MoodsMode) ----
        // Per-outcome class stats: [0]=count, [1]=Stopwatch ticks of thread-time.
        // Shown in the end-of-scan breakdown; the cached/skip classes feed the ETA
        // model's "known tracks are near-free" term.
        static readonly ConcurrentDictionary<string, long[]> _classStats = new ConcurrentDictionary<string, long[]>();
        // Bytes fully analyzed (cache misses — the Essentia-dominated cost), total +
        // trailing-window events for the live MB/s rate on the progress line.
        static long _analyzedBytesTotal;
        static readonly ConcurrentQueue<(double AtSecs, long Bytes)> _rateEvents = new ConcurrentQueue<(double, long)>();
        const double RateWindowSecs = 120.0;
        // Audio-duration analyzed (decoded length when Essentia reports it, claimed
        // otherwise) — total + trailing-window events for the Nx-realtime headline.
        // Duration is the honest throughput unit: a FLAC and a low-bitrate MP3 of the
        // same content cost the same to scan but differ wildly in MB, so MB/s is a
        // relative number with no transform; audio-seconds per wall-second needs none.
        static long _analyzedAudioMsTotal;
        // Duration-based progress: total audio in the scan's work list (set at preflight)
        // and audio processed so far (accumulated per completed track). The progress % is
        // audio-time through the library, not track position — a 3h podcast and a 3m song
        // move the bar very differently, so count% and duration% legitimately disagree.
        static long _scanAudioMsTotal;
        static long _processedAudioMsTotal;
        static readonly ConcurrentQueue<(double AtSecs, long AudioMs)> _audioRateEvents = new ConcurrentQueue<(double, long)>();
        // ETA model pre-flight (set by MoodsMode; -1 = model unavailable, naive ETA):
        // tracks absent from the existing catalog need the full Essentia pass; the
        // XML <Size> key supplies their byte total so remaining work is bytes-costed
        // at the measured rate instead of count-costed at a blended average.
        static int _etaNewTotal = -1;
        static int _etaNewDone;
        static long _etaNewBytesTotal;
        static long _etaNewBytesDone;
        static int _scanParallelism;
        // Periodic incremental save: TIME-based (2026-07-28) — fires on the first
        // analysis completion >= SavePeriodSecs after the previous save. A count
        // interval bounds work-at-risk in TRACKS, which on a slow machine could mean
        // hours between saves; a time period bounds it in MINUTES on any machine.
        // Crash/cancel resilience is the whole point of ongoing saves — Ctrl+C
        // additionally always flushes via the unconditional final SaveResults.
        const double SavePeriodSecs = 300;
        // Measured periodic-save cost (Stopwatch ticks + count), fed to the ETA:
        // the analysis-only model couldn't see the save tax at all, which is why
        // resume/rescan estimates read far low on large catalogs (2026-07-28).
        static long _saveTicksTotal;
        static int _saveCount;
        // Duration-based ETA model: Essentia cost scales with AUDIO DURATION, not
        // file size (a 3-hour 64kbps podcast costs ~90x a 4-minute FLAC of the same
        // byte size). The XML Total Time supplies per-track durations up front; the
        // measured real-time-factor (analysis thread-seconds per audio-second) is
        // stable from the first completion, unlike the byte-rate window which is
        // hostage to whichever file sizes happen to finish first.
        static long _etaNewAudioMsTotal;
        static long _etaNewAudioMsDone;
        static long _rtfAnalyzeTicks;   // thread ticks, only for tracks with known duration
        static long _rtfAudioMs;        // matching audio-ms sum
        static long _rtfTrackCount;     // matching track count — lets the summary report average length

        /// <summary>The default --help front page. The full flag listing lives in
        /// PrintHelpAll (truedat --help all) — most flags are single-purpose
        /// maintenance verbs the everyday scan never needs, and burying the
        /// canonical zero-arg run under 140 lines of them was the complaint that
        /// produced this split.</summary>
        static void PrintHelp()
        {
            Console.WriteLine("Usage: truedat.exe [<path-to-iTunes-Music-Library.xml>] [options]");
            Console.WriteLine();
            Console.WriteLine("Zero-arg is the canonical run: truedat auto-discovers the iTunes XML (exe-dir parent,");
            Console.WriteLine("exe dir, then current directory) and runs the default full library scan, writing");
            Console.WriteLine("mbxmoods.json next to the XML (Essentia analysis, cache-aware).");
            Console.WriteLine();
            Console.WriteLine("Everyday:");
            Console.WriteLine("  (zero-arg)            scan the library");
            Console.WriteLine("  --refresh             re-analyze entries missing the newest feature fields");
            Console.WriteLine("                        (resumable; run in sessions until coverage completes)");
            Console.WriteLine("  --stats [path]        read-only catalog summary + recommended next commands");
            Console.WriteLine("  --verify --backfill   integrity check + fill missing fields (no re-analysis)");
            Console.WriteLine("  --duplicates [path]   duplicates report + interactive review page");
            Console.WriteLine("  --preview [path]      what a scan WOULD do (work plan + review candidates)");
            Console.WriteLine();
            Console.WriteLine($"Options: -p N|max (parallelism, default {Math.Max(1, Environment.ProcessorCount - 2)} = cores-2)   --audit (log to truedat.log)");
            Console.WriteLine("         --pause (hold console open at exit)");
            Console.WriteLine();
            Console.WriteLine("Everything else: truedat --help all");
        }

